"use client";

import { useState } from "react";
import type { Branch } from "@/lib/types";
import { EdaOverview } from "./eda-overview";
import { EdaSku } from "./eda-sku";
import { EdaBranch } from "./eda-branch";
import { EdaBranchSku } from "./eda-branch-sku";
import { EdaRegion } from "./eda-region";
import { EdaBrand } from "./eda-brand";

export function EdaModule({ branches, branchCode, onBranchChange }: { branches: Branch[]; branchCode: string; onBranchChange: (value: string) => void }) {
  const [activeTab, setActiveTab] = useState("overview");

  const sidebarItems = [
    { id: "overview", label: "Tổng quan" },
    { id: "sku", label: "SKU" },
    { id: "branch", label: "Chi nhánh" },
    { id: "branch_sku", label: "Chi nhánh x SKU" },
    { id: "region", label: "Vùng" },
    { id: "brand", label: "Thương hiệu" },
  ];

  return (
    <section className="module" style={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
      <div className="module-heading">
        <div>
          <p className="eyebrow">MODULE 02</p>
          <h2>EDA chuyên sâu</h2>
        </div>
        <select value={branchCode} onChange={(event) => onBranchChange(event.target.value)}>
          <option value="__ALL__">Toàn hệ thống</option>
          {branches.map((branch) => <option key={branch.branch_code} value={branch.branch_code}>{branch.branch_code} · {branch.branch_name}</option>)}
        </select>
      </div>
      
      <div style={{ display: 'flex', gap: '32px', marginTop: '24px', flexGrow: 1 }}>
        <aside style={{ width: '220px', flexShrink: 0, display: 'flex', flexDirection: 'column', gap: '4px', borderRight: '1px solid var(--border-color, #eaeaea)', paddingRight: '16px' }}>
          {sidebarItems.map(item => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              style={{
                textAlign: 'left',
                padding: '10px 16px',
                background: activeTab === item.id ? 'var(--bg-accent, #f4f4f5)' : 'transparent',
                color: activeTab === item.id ? 'var(--fg-primary, #09090b)' : 'var(--fg-muted, #71717a)',
                fontWeight: activeTab === item.id ? 500 : 400,
                border: 'none',
                borderRadius: '6px',
                cursor: 'pointer',
                transition: 'all 0.2s',
                fontSize: '14px'
              }}
            >
              {item.label}
            </button>
          ))}
        </aside>
        
        <div style={{ flexGrow: 1, minWidth: 0 }}>
          {activeTab === 'overview' && <EdaOverview branches={branches} branchCode={branchCode} onBranchChange={onBranchChange} />}
          {activeTab === 'sku' && <EdaSku branchCode={branchCode} />}
          {activeTab === 'branch' && <EdaBranch branchCode={branchCode} />}
          {activeTab === 'branch_sku' && <EdaBranchSku branchCode={branchCode} />}
          {activeTab === 'region' && <EdaRegion branchCode={branchCode} />}
          {activeTab === 'brand' && <EdaBrand branchCode={branchCode} />}
        </div>
      </div>
    </section>
  );
}
